/* Retained prototype layers. Display names are legacy labels, not provenance. */
(function (root) {
  "use strict";
  const DATASETS = Object.freeze([
    Object.freeze({
      id: "legacy_2100", label: "Flood Extent 2100 — 1% AEP (climate change scenario)",
      file: "data/flood_extent_2100.json", scenario: "planning_overlay_union",
      data_kind: "planning_overlay", synthetic: false,
      description: "The Flood Extent 2100 layer is derived from the Special Building Overlay (SBO2 and SBO3). The overlay aims “to identify land in areas that may be inundated by the combined effects of the 1% Annual Exceedance Probability (AEP) flood event incorporating an 18.5% increase in rainfall intensity due to climate change by the year 2100” [1]. The data is available on Digital Twin Victoria [2].",
      references: Object.freeze([
        Object.freeze({
          marker: "[1]",
          text: "Victorian Government, “Schedule 3 to Clause 44.05 Special Building Overlay (SBO3),” Melbourne Planning Scheme, Amendment C384melb, Dec. 13, 2024.",
          url: "https://stfpbsprodapp01.blob.core.windows.net/amendmentfiles/44.05_melb%20Schedule%203%20Special%20Building%20Overlay_470cabfd-be7e-ea11-a811-000d3acb8f76_9798ddfa-228d-4bbe-ace3-b8f0e1a4cad5.pdf",
        }),
        Object.freeze({
          marker: "[2]",
          text: "Digital Twin Victoria, “Special Building Overlay,” Victorian Government.",
          url: "https://digitaltwin.vic.gov.au/portals/44/map/?https%3A%2F%2Fdigitaltwin.vic.gov.au%2Fapi%2Fv1%2Fterria%2Fportal%2F44%2Fcatalog.json&share=3abab66a-a24e-4cd6-af08-bc58c55bef6f",
        }),
      ]),
      source_url: "scripts/transform.py",
    }),
    Object.freeze({
      id: "demo_2010", label: "Flood Extent 2010 (example only)",
      file: "data/flood_extent_2010.json", scenario: "synthetic_demo_2010",
      data_kind: "synthetic_demo", synthetic: true,
      description: "The Flood Extent 2010 layer is a proof of concept derived from a placeholder dataset for the 2010 flood and does not represent the actual 2010 flood extent. The dataset was generated by taking a subset (85%) of the Flood Extent 2100 dataset and adding some random noise. The actual dataset, which isn't publicly available, was generated by Water Technology for the City of Melbourne in 2017 as part of their flood modelling to support the C384 Planning Amendment [3].",
      // Numbered after the 2100 entry's [1] and [2]: one sequence across the sources panel.
      references: Object.freeze([
        Object.freeze({
          marker: "[3]",
          text: "L. Cunningham and C. Marchenay, “Elizabeth Street, Melbourne Flood Modelling Report,” Water Technology Pty Ltd, prepared for City of Melbourne, Rep. 3611-01 R01 V07, Aug. 2017. Published as Amendment C384melb Background Document, Technical Report 04.",
          url: "https://stfpbsprodapp01.blob.core.windows.net/amendmentfiles/C384melb%20Background%20Doc%20-%20Technical%20Report%2004%20-%20Elizabeth%20Street%20Melbourne%20Flood%20Modelling%20Report%20(Water%20Technology,%20April%202020)_470cabfd-be7e-ea11-a811-000d3acb8f76_d3c64fc7-0cb7-4053-8fc0-7e60e9b901c1.PDF",
        }),
      ]),
      source_url: "scripts/transform.py",
    }),
  ]);

  function validateExtent(data, dataset) {
    const expected = DATASETS.find((entry) => entry.id === dataset?.id);
    if (!expected || ["file", "scenario", "data_kind", "synthetic"].some((field) => dataset[field] !== expected[field])) {
      throw new Error("Unknown or inconsistent prototype dataset");
    }
    if (!data || data.error || data.exceededTransferLimit === true || data.type !== "FeatureCollection" || !Array.isArray(data.features) || !data.features.length) {
      throw new Error("Missing or incomplete prototype features");
    }
    for (const feature of data.features) {
      if (feature?.type !== "Feature" || !feature.geometry || !feature.properties ||
          ["scenario", "data_kind", "synthetic"].some((field) => feature.properties[field] !== expected[field])) {
        throw new Error("Prototype layer provenance does not match its catalogue entry");
      }
    }
    return data;
  }

  const api = { DATASETS, validateExtent };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.PrototypeData = api;
})(typeof window === "undefined" ? globalThis : window);
